	idx, err := helpers.BeaconProposerIndex(ctx, parentState)
	if err != nil {
		return nil, err
	}
	if blk.Block().ProposerIndex() != idx {
		s.setBadBlock(ctx, blockRoot)
		return nil, errors.New("incorrect proposer index")
	}
	return parentState, nil
}

